// Builds orem-spots.json from the researched rows below. Run: node build-spots.mjs
import fs from 'node:fs';

// coordsSource codes (explained in orem-spots-notes.md)
const SSC = 'ssc-app: business location from the Starving Student Card app data (fetched 2026-10-15); OSM reverse-geocode at that point names this business';
const SSCX = 'ssc-app: business location from the Starving Student Card app data (fetched 2026-10-15); address matches by street/number, no named OSM POI';
const POI = 'osm-poi: OpenStreetMap named feature via Nominatim search (2026-10-15)';
const ADDR = 'osm-address: OpenStreetMap house-number geocode of the street address via Nominatim (2026-10-15)';
const APPROX = 'approx: nearest OSM feature (mall/street/park centroid), may be off by 100-300 m';

const APP = 'Starving Student Card app public preview (app.starvingstudentcard.com/preview), fetched 2026-10-15';
const CARD = '2022-23 Utah County printed card (expired)';

// r(id, name, category, city, address, [lat,lng], coordsSource, cost, priceNote, hours, season, indoor, tags, sourceUrl, ssc, sscSource, verifiedOpen, openEvidence)
const rows = [];
function r(id, name, category, city, address, ll, coordsSource, costPerCouple, priceNote, hours, season, indoor, tags, sourceUrl, ssc, sscSource, verifiedOpen, openEvidence) {
  rows.push({ id, name, category, city, address, lat: ll ? ll[0] : null, lng: ll ? ll[1] : null, coordsSource, costPerCouple, priceNote, hours, season, indoor, tags, sourceUrl, ssc, sscConfirmed: false, sscSource: ssc ? sscSource : null, verifiedOpen, openEvidence });
}

